#!/usr/bin/env python3
"""NEXO private memory 1.0.1. No network, no Tower writes, no scheduler changes."""
import base64, hashlib, io, json, sys, tempfile, zipfile
from pathlib import Path
_BUNDLE = ""
_SHA256 = "31a7494383476a79d37321c4c8c189c993c63edf3e1a13fb7b497d52138afe35"

def main():
    raw = base64.b64decode(_BUNDLE, validate=True)
    if hashlib.sha256(raw).hexdigest() != _SHA256:
        raise RuntimeError("Memory package integrity failure")
    if sys.argv[1:] == ["--version"]:
        print(json.dumps({"version": "1.0.1", "package_sha256": _SHA256, "tower_mutation": False}))
        return 0
    with tempfile.TemporaryDirectory(prefix="nexo-memory-") as folder:
        root = Path(folder)
        with zipfile.ZipFile(io.BytesIO(raw)) as archive:
            for member in archive.infolist():
                target = (root / member.filename).resolve()
                if root.resolve() not in target.parents:
                    raise RuntimeError("Invalid bundle path")
            archive.extractall(root)
        sys.path.insert(0, str(root))
        from runtime.nexo_agent_api.memory_cli import main as run
        return run(sys.argv[1:])

if __name__ == "__main__":
    raise SystemExit(main())